import json

def transform_div2_1(cell):
    """5//2=2, but we need 5->1. Try (cell+1)//3 or other"""
    if cell == 5:
        return 1
    else:
        return 0

def transform_div3(cell):
    """5//3=1, 2//3=0"""
    return cell // 3 if cell < 3 else 1

def transform_mod3(cell):
    """5%3=2, 2%3=2. Not quite."""
    return cell % 3

def transform_diff10(cell):
    """(cell+1)//4: 5->1, 2->0. Also 1->0."""
    if cell == 5:
        return 1
    if cell == 1:
        return 0
    return 0

def transform_diff5(cell):
    """Try: 5->1, 2->1. Both become 1."""
    if cell == 5:
        return 1
    return 1

def transform_diff2(cell):
    """Try: 5->1, 2->0. Similar to my earlier try."""
    if cell == 5:
        return 1
    elif cell == 2:
        return 0
    return 0

def transform_map25(cell):
    """Map both 2 and 5 to single output. 2->0, 5->1."""
    return 1 if cell == 5 else 0 if cell == 2 else cell

# Test on demo1
def test_demo_names(names_funcs):
    print("Demo1 check:")
    for name, func in names_funcs:
        res5 = func(5)
        res1 = func(1) if hasattr(func, '__call__') else 'N/A'
        print(f"  {name}: 5->{res5}, 1->{res1} (needs 5->1, 1->0)")

demo_names_funcs = [
    ("div2_1", transform_div2_1),
    ("diff10", transform_diff10),
    ("map25", transform_map25)
]
test_demo_names(demo_names_funcs)

# Test on test input
