# What if the rule is about distance from a target value?
def transform_target5(cell):
    """5 is target->1, others->0"""
    return 1 if cell == 5 else 0

def transform_target2(cell):  
    """Target is 2. 2->1, 5->0"""
    return 1 if cell == 2 else 0

# Check demo1 compatibility
